const globalTextTranslations: Record<LanguageCode, TextDictionary> = Object.fromEntries(
  (Object.keys(supportedLanguages) as LanguageCode[]).map(language => [
    language,
    {
      ...Object.fromEntries(
        (Object.keys(english) as TranslationKey[]).map(key => [english[key], translations[language][key] ?? english[key]])
      ),
      ...commonUiTranslations[language]
    }
  ])
) as Record<LanguageCode, TextDictionary>;

const reverseTextTranslations: Record<LanguageCode, TextDictionary> = Object.fromEntries(
  (Object.keys(supportedLanguages) as LanguageCode[]).map(language => [
    language,
    Object.fromEntries(Object.entries(globalTextTranslations[language]).map(([source, translated]) => [translated, source]))
  ])
) as Record<LanguageCode, TextDictionary>;

const allReverseTextTranslations: TextDictionary = Object.assign({}, ...Object.values(reverseTextTranslations));

const STORAGE_KEY = 'q_language';

const detectLanguage = (): LanguageCode => {
  if (typeof navigator === 'undefined') return 'en';
  for (const locale of navigator.languages ?? [navigator.language]) {
    const code = locale.toLowerCase().split('-')[0] as LanguageCode;
    if (code in supportedLanguages) return code;
  }
  return 'en';
};

const preserveWhitespace = (input: string, replacement: string) => {
  const [, leading = '', body = input, trailing = ''] = input.match(/^(\s*)(.*?)(\s*)$/s) ?? [];
  return `${leading}${replacement || body}${trailing}`;
};

interface LanguageValue {
  language: LanguageCode;
  setLanguage: (value: LanguageCode) => void;
  t: (key: TranslationKey) => string;
  translateText: (value: string) => string;
  locale: string;
}

const LanguageContext = createContext<LanguageValue | null>(null);

export const LanguageProvider: React.FC<React.PropsWithChildren> = ({ children }) => {
  const [language, setLanguage] = useState<LanguageCode>(() => {
    const saved = typeof window !== 'undefined' ? localStorage.getItem(STORAGE_KEY) as LanguageCode | null : null;
    return saved && saved in supportedLanguages ? saved : detectLanguage();
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, language);
    document.documentElement.lang = language === 'zh' ? 'zh-Hans' : language;
    document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr';
  }, [language]);

  const value = useMemo<LanguageValue>(() => {
    const t = (key: TranslationKey) => translations[language][key] ?? english[key];
    const translateText = (value: string) => {
      const trimmed = value.trim();
      if (!trimmed) return value;
      const englishSource = allReverseTextTranslations[trimmed] ?? trimmed;
      const translated = language === 'en' ? englishSource : globalTextTranslations[language][englishSource] ?? englishSource;
      return preserveWhitespace(value, translated);
    };

    return {
      language,
      setLanguage,
      t,
      translateText,
      locale: language === 'zh' ? 'zh-CN' : language
    };
  }, [language]);

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
};

export const useLanguage = () => {
  const value = useContext(LanguageContext);
  if (!value) throw new Error('useLanguage must be used within LanguageProvider');
  return value;
};
